sql.where:
ar.deleted = 0

  AND ar.status = #{status}


  AND ar.company_id = #{companyId}


  AND ar.vessel_id = #{vesselId}


  AND (
       ar.request_no LIKE '%' + #{keyword} + '%'
    OR ar.work_type  LIKE '%' + #{keyword} + '%'
    OR c.name        LIKE '%' + #{keyword} + '%'
    OR v.name        LIKE '%' + #{keyword} + '%'
  )


  AND ar.planned_end_date >= #{dateFrom}


  AND ar.planned_start_date <= #{dateTo}
